#!/usr/bin/env bash
set -euo pipefail

# Run one mpnn invocation, logging failures and continuing with the next
# sample instead of aborting the whole batch. Exit code 1 signals a skipped
# sample; the script still succeeds overall so pipeline users see a clean run.
run_mpnn() {
  if ! mpnn "$@"; then
    echo "[run_mpnn.sh] mpnn failed (see traceback above); skipping this sample." >&2
    return 1
  fi
}

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

MPNN_CKPT="${1:-/path/to/proteinmpnn_v_48_020.pt}"

echo "ProteinMPNN checkpoint: ${MPNN_CKPT}"
echo "Delivery root: ${ROOT}"

echo "============================================================"
echo "[1/4983] train_0"
mkdir -p "${ROOT}/mpnn_outputs/train_0"

if ! run_mpnn \
  --model_type \
  protein_mpnn \
  --checkpoint_path \
  "${MPNN_CKPT}" \
  --is_legacy_weights \
  True \
  --structure_path \
  "${ROOT}/structures/train_0_4xe6_X_rec.pdb" \
  --fixed_residues \
  '["X92", "X20", "X50", "X7", "X27", "X5"]' \
  --out_directory \
  "${ROOT}/mpnn_outputs/train_0" \
  --write_fasta \
  True \
  --write_structures \
  True \
  --name \
  train_0
then
  : # sample completed
else
  echo "[run_mpnn.sh] mpnn failed (see traceback above); skipping this sample."
fi
echo "============================================================"
echo "[2/4983] train_1"
mkdir -p "${ROOT}/mpnn_outputs/train_1"

